import{_ as i,o as n,c as o,a2 as s}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"Join Flow Semantics","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/join-semantics.md","filePath":"contracts/join-semantics.md","lastUpdated":1780254295000}'),t={name:"contracts/join-semantics.md"};function a(r,e,l,d,c,p){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="join-flow-semantics" tabindex="-1">Join Flow Semantics <a class="header-anchor" href="#join-flow-semantics" aria-label="Permalink to &quot;Join Flow Semantics&quot;">​</a></h1><p>This document defines the contract for space join flows between backend (daemon/bot) and desktop.</p><p><strong>Status:</strong> Transitional - some semantics need formalization</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The join flow is <strong>asynchronous</strong>: <code>JoinSpace</code> returns a submission ID, and the approval/rejection arrives later via <code>StreamEvents</code>. This is intentional for offline-friendly P2P operation.</p><p>User-facing summary:</p><ul><li>submitting a request does not make the device a member yet</li><li>pending means the request is still waiting for an approver&#39;s decision</li><li>approval can be recorded before it is delivered if the requester is offline</li><li>delivery failures can be retried later when peers become reachable again</li></ul><h2 id="rpc-contracts" tabindex="-1">RPC Contracts <a class="header-anchor" href="#rpc-contracts" aria-label="Permalink to &quot;RPC Contracts&quot;">​</a></h2><h3 id="daemon-joinspace" tabindex="-1"><code>Daemon/JoinSpace</code> <a class="header-anchor" href="#daemon-joinspace" aria-label="Permalink to &quot;`Daemon/JoinSpace`&quot;">​</a></h3><p><strong>Contract:</strong></p><ul><li><strong>Input:</strong> <code>space_id</code>, <code>target_peer_id</code>, <code>target_multiaddrs</code>, optional <code>display_name</code>/<code>device_name</code></li><li><strong>Output:</strong> <code>request_id</code> (opaque tracking ID)</li><li><strong>Side effects:</strong><ol><li>Persists outgoing join request to <code>join_requests</code> table (<code>is_outgoing=true</code>)</li><li>Enqueues delivery via mailbox (<code>mailbox</code> table)</li><li>Emits <code>JoinSubmitEvent</code> via <code>StreamEvents</code></li><li>Sends libp2p <code>/soma/join/1</code> request to target peer</li></ol></li><li><strong>Does NOT indicate approval or rejection</strong></li><li><strong>Errors:</strong><ul><li><code>INVALID_ARGUMENT</code>: missing required fields</li><li><code>INTERNAL</code>: peer not running, enqueue failed</li></ul></li></ul><p><strong>Semantics:</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Submit → Receive request_id → Wait for JoinDecisionEvent → Apply decision</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Client responsibilities:</strong></p><ul><li>Do not assume immediate success</li><li>Subscribe to <code>StreamEvents</code> before or immediately after calling</li><li>Correlate events via <code>request_id</code> if needed</li></ul><hr><h3 id="daemon-listjoinrequests" tabindex="-1"><code>Daemon/ListJoinRequests</code> <a class="header-anchor" href="#daemon-listjoinrequests" aria-label="Permalink to &quot;`Daemon/ListJoinRequests`&quot;">​</a></h3><p><strong>Contract:</strong></p><ul><li><strong>Scope:</strong> Incoming pending join requests where this peer is the target (<code>is_outgoing=false</code>, <code>status=pending</code>)</li><li><strong>Does NOT include:</strong> Outgoing requests submitted by this peer</li></ul><p><strong>Semantics:</strong></p><ul><li>Used by owners/bots to see pending approvals</li><li>To track outgoing requests, correlate with <code>JoinSubmitEvent</code> events</li></ul><hr><h3 id="daemon-decidejoin" tabindex="-1"><code>Daemon/DecideJoin</code> <a class="header-anchor" href="#daemon-decidejoin" aria-label="Permalink to &quot;`Daemon/DecideJoin`&quot;">​</a></h3><p><strong>Contract:</strong></p><ul><li><strong>Input:</strong> <code>request_id</code>, <code>approve</code>, optional <code>role</code>, optional <code>reason</code></li><li><strong>Authorization:</strong> Caller must be space owner OR hold valid issuer capability</li><li><strong>Side effects:</strong><ol><li>Records decision in <code>join_decisions</code> table</li><li>On approve: creates <code>space_memberships</code> row with signed capability</li><li>Enqueues delivery via mailbox</li><li>Sends libp2p <code>/soma/join-decision/1</code> to requester if online</li></ol></li></ul><hr><h2 id="event-contracts" tabindex="-1">Event Contracts <a class="header-anchor" href="#event-contracts" aria-label="Permalink to &quot;Event Contracts&quot;">​</a></h2><h3 id="joinsubmitevent" tabindex="-1"><code>JoinSubmitEvent</code> <a class="header-anchor" href="#joinsubmitevent" aria-label="Permalink to &quot;`JoinSubmitEvent`&quot;">​</a></h3><p>Emitted when <code>JoinSpace</code> is called locally.</p><p><strong>Fields:</strong></p><ul><li><code>request_id</code>: matches RPC response</li><li><code>target_peer_id</code>: the peer the request was sent to</li></ul><p><strong>Duplication:</strong></p><ul><li>Currently <strong>can emit multiple times</strong> if <code>StreamEvents</code> reconnects</li><li>No deduplication on server side</li><li><strong>Client must deduplicate</strong> based on <code>request_id</code> + timestamp if needed</li></ul><hr><h3 id="joindecisionevent" tabindex="-1"><code>JoinDecisionEvent</code> <a class="header-anchor" href="#joindecisionevent" aria-label="Permalink to &quot;`JoinDecisionEvent`&quot;">​</a></h3><p>Emitted when a join decision is received from a remote peer.</p><p><strong>Fields:</strong></p><ul><li><code>from_peer_id</code>: the peer that sent the decision</li><li><code>decision</code>: the <code>JoinDecision</code> proto</li></ul><p><strong>Handling:</strong></p><ul><li>Backend persists decision and membership on receipt</li><li>Desktop receives via event stream and updates UI state</li></ul><hr><h3 id="joinfailedevent" tabindex="-1"><code>JoinFailedEvent</code> <a class="header-anchor" href="#joinfailedevent" aria-label="Permalink to &quot;`JoinFailedEvent`&quot;">​</a></h3><p>Emitted when an outgoing join request cannot be delivered.</p><p><strong>Fields:</strong></p><ul><li><code>target_peer_id</code>: the peer that was unreachable</li><li><code>error</code>: error message</li></ul><p><strong>Handling:</strong></p><ul><li>Request is persisted and retried via mailbox when peer comes online</li><li>Client may show retry status</li></ul><hr><h2 id="pending-state-encoding-current" tabindex="-1">Pending State Encoding (Current) <a class="header-anchor" href="#pending-state-encoding-current" aria-label="Permalink to &quot;Pending State Encoding (Current)&quot;">​</a></h2><p><strong>Problem:</strong> The proto has no <code>JoinDecisionType::Pending</code> enum value.</p><p><strong>Current workaround:</strong></p><ul><li>Bot returns <code>JoinDecision</code> with: <ul><li><code>decision = JoinDecisionType::JoinRejected</code></li><li><code>decision_id = &quot;reject-pending manual approval&quot;</code></li><li><code>reason = &quot;pending manual approval&quot;</code></li></ul></li><li>Handlers check <code>decision_id.starts_with(&quot;reject-pending&quot;)</code> to ignore these placeholders</li></ul><p><strong>Risks:</strong></p><ol><li>Relies on string prefix in <code>decision_id</code> field</li><li><code>JoinRejected</code> enum value is semantically incorrect</li><li>Clients cannot distinguish &quot;rejected&quot; from &quot;waiting for approval&quot;</li></ol><p><strong>Proposed fix (Phase 2):</strong></p><p>Option A: Add <code>JoinDecisionType::PENDING</code> to proto</p><div class="language-proto vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">proto</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> JoinDecisionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  JOIN_DECISION_UNSPECIFIED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  JOIN_APPROVED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  JOIN_REJECTED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  JOIN_BLOCKED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  JOIN_PENDING </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// NEW: explicit pending state</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Option B: Keep current encoding but document clearly</p><ul><li>Add comment to proto explaining <code>reject-pending</code> prefix convention</li><li>Document in this file as intentional workaround</li></ul><hr><h2 id="readblobresponse-mime-adjacent-issue" tabindex="-1"><code>ReadBlobResponse.mime</code> (Adjacent Issue) <a class="header-anchor" href="#readblobresponse-mime-adjacent-issue" aria-label="Permalink to &quot;`ReadBlobResponse.mime` (Adjacent Issue)&quot;">​</a></h2><p><strong>Current behavior:</strong></p><ul><li><code>UploadBlob</code> stores the provided MIME type in <code>blobs.mime</code></li><li><code>ReadBlob</code> returns hardcoded <code>mime = &quot;application/octet-stream&quot;</code></li><li>Stored MIME is NOT used</li></ul><p><strong>Fix:</strong></p><ul><li>Update <code>ReadBlob</code> to return stored MIME from <code>BlobMetadata</code></li><li>Fallback to <code>application/octet-stream</code> if missing</li></ul><hr><h2 id="contract-test-requirements" tabindex="-1">Contract Test Requirements <a class="header-anchor" href="#contract-test-requirements" aria-label="Permalink to &quot;Contract Test Requirements&quot;">​</a></h2><p>To prevent drift, the following should be tested:</p><ol><li><strong>Daemon proto smoke:</strong> Call each RPC against a running daemon, verify response structure</li><li><strong>Join flow smoke:</strong> Submit join, verify event emission, receive decision</li><li><strong>Event dedup:</strong> Verify <code>JoinSubmitEvent</code> behavior on reconnect</li><li><strong>Pending encoding:</strong> Verify <code>reject-pending</code> handling in daemon/botd handlers</li></ol>',70)])])}const g=i(t,[["render",a]]);export{u as __pageData,g as default};
